open(P+'lib.py','w').write('''def fill_quadrant_spirals(grid, color=3, fill=4):
    """Fill each quadrant around a full row/column cross of `color` with a staircase spiral of
    `fill` anchored at the grid corner of that quadrant: relative to the anchor, cell (i, j)
    is filled iff (i odd and j <= i) or (j odd and i <= j)."""
    out = [list(r) for r in grid]
    h, w = len(grid), len(grid[0])
    R = next(i for i in range(h) if all(v == color for v in grid[i]))
    C = next(j for j in range(w) if all(grid[i][j] == color for i in range(h)))
    for r0, r1, c0, c1 in [(0, R, 0, C), (0, R, C + 1, w),
                           (R + 1, h, 0, C), (R + 1, h, C + 1, w)]:
        for i in range(r0, r1):
            for j in range(c0, c1):
                a = (i - r0) if r0 + r1 > h else (r1 - 1 - i)
                b = (j - c0) if c0 + c1 > w else (c1 - 1 - j)
                if (a % 2 == 1 and b <= a) or (b % 2 == 1 and a <= b):
                    out[i][j] = fill
    return out
''')
